def process(fraudReports2024Load):
    import pandas as pd
    import numpy as np
    import re

    raw = fraudReports2024Load.copy()

    # Locate the embedded header row (contains 'Military Status' and 'Median Fraud Loss')
    def is_header_row(row):
        vals = [str(v).strip() for v in row.tolist()]
        joined = " | ".join(vals)
        return ('Military Status' in joined) and ('Median Fraud Loss' in joined)

    header_idx = None
    for i in range(len(raw)):
        if is_header_row(raw.loc[i]):
            header_idx = i
            break
    if header_idx is None:
        return pd.DataFrame([{
            'error': 'Could not locate header row containing Military Status and Median Fraud Loss',
            'sampleRow0': str(raw.iloc[0].tolist()),
            'sampleRow2': str(raw.iloc[2].tolist())
        }])

    header = raw.loc[header_idx].tolist()
    df = raw.loc[header_idx + 1:].copy()
    df.columns = header
    df = df.dropna(how='all')

    # Clean column names
    df.columns = [str(c).strip() for c in df.columns]

    ms_col = 'Military Status'
    if ms_col not in df.columns:
        # Sometimes stray spaces
        alt = [c for c in df.columns if str(c).strip().lower() == 'military status']
        if alt:
            ms_col = alt[0]
        else:
            return pd.DataFrame([{'error': 'Military Status column not found after header assignment', 'columns': str(list(df.columns))}])

    mfl_col = 'Median Fraud Loss'
    if mfl_col not in df.columns:
        alt = [c for c in df.columns if str(c).strip().lower() == 'median fraud loss']
        if alt:
            mfl_col = alt[0]
        else:
            return pd.DataFrame([{'error': 'Median Fraud Loss column not found after header assignment', 'columns': str(list(df.columns))}])

    df[ms_col] = df[ms_col].astype(str).str.strip()

    # Keep only branch rows
    branch = df[df[ms_col].str.startswith('Branch:', na=False)].copy()
    if branch.empty:
        branch = df[df[ms_col].str.contains('Branch', na=False)].copy()

    branch['Branch'] = branch[ms_col].str.replace(r'^Branch:\s*', '', regex=True).str.strip()

    def parse_money(x):
        if pd.isna(x):
            return np.nan
        s = str(x)
        # extract first number-like token
        m = re.findall(r"[-+]?(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?", s)
        if not m:
            return np.nan
        return float(m[0].replace(',', ''))

    branch['Median Fraud Loss (numeric)'] = branch[mfl_col].apply(parse_money)

    out = branch[['Branch', mfl_col, 'Median Fraud Loss (numeric)']].rename(columns={mfl_col: 'Median Fraud Loss'})
    out = out.sort_values('Median Fraud Loss (numeric)', ascending=False, na_position='last')

    return out.head(1).reset_index(drop=True)
